import { useState, useEffect } from 'react';
import './App.css';

function App() {
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    setIsVisible(true);
  }, []);

  const scrollToInfo = () => {
    window.scrollTo({
      top: window.innerHeight,
      behavior: 'smooth'
    });
  };

  const joinDiscord = () => {
    window.open('https://discord.gg/ASSnBjyt', '_blank');
  };

  return (
    <div className="gaming-site">

      {/* Floating Discord Button */}
  <div className="floating-discord-btn" style={{ position: 'fixed', bottom: 32, right: 32, left: 'auto', top: 'auto', zIndex: 1000, pointerEvents: 'auto' }}>
        <button 
          className="discord-float-button"
          onClick={joinDiscord}
          title="Join Discord Server"
          style={{
            display: 'flex',
            alignItems: 'center',
            gap: 8,
            background: '#5865F2',
            color: '#fff',
            border: 'none',
            borderRadius: 32,
            padding: '16px 28px',
            fontWeight: 700,
            fontSize: '1.1rem',
            boxShadow: '0 4px 24px #0004',
            cursor: 'pointer',
            transition: 'background 0.2s, box-shadow 0.2s',
          }}
        >
          <span className="discord-icon" style={{ fontSize: 24 }}>💬</span>
          <span className="discord-text">Join discord and start playing</span>
        </button>
      </div>

      {/* Hero Section - Full Screen */}
      <section className="hero-section">
        {/* Video Background */}
        <div className="video-background">
          {/* You can replace this with an actual video */}
          <div className="video-placeholder">
            {/* Animated background pattern */}
            <div className="animated-bg">
              {[...Array(50)].map((_, i) => (
                <div
                  key={i}
                  className="particle"
                  style={{
                    left: Math.random() * 100 + '%',
                    top: Math.random() * 100 + '%',
                    animationDelay: Math.random() * 3 + 's',
                    animationDuration: (3 + Math.random() * 4) + 's'
                  }}
                />
              ))}
            </div>
          </div>
          <div className="video-overlay" />
        </div>

        {/* Navigation */}
        {/* Navigation removed per user request */}

        {/* Hero Content */}
        <div className="hero-content">
          <div className={`hero-text ${isVisible ? 'animate' : ''}`}>
            <h1 className="hero-title">
              DEMOCRACIV
              <span className="highlight"> No quit Civ 5 </span>
              DISCORD SERVER
            </h1>

            <p className="hero-subtitle">
              Join the Democraciv civ 5 multipayer community with democratic governance, 
              ELO ranking system, and enforced fair play rules for a better civ 5 experience.
            </p>

            {/* Call to Action Buttons */}
            <div className="cta-buttons">
              <button 
                className="btn btn-primary"
                onClick={scrollToInfo}
              >
                <span>�️ Learn About Democraciv</span>
                <div className="btn-glow"></div>
              </button>

              <button 
                className="btn btn-discord"
                onClick={joinDiscord}
              >
                <span>💬 Join Discord Server</span>
                <div className="btn-glow"></div>
              </button>
            </div>

            {/* Server Stats */}
            <div className="hero-stats">
              <div className="stat">
                <div className="stat-number">Vanilla BNW Mod</div>
                <div className="stat-label">(kekmod) Democraciv Only </div>
              </div>
              <div className="stat">
                <div className="stat-number">100%</div>
                <div className="stat-label">Fair Play</div>
              </div>
              <div className="stat">
                <div className="stat-number">24/7</div>
                <div className="stat-label">Active Community</div>
              </div>
            </div>
          </div>
        </div>

        {/* Scroll Indicator */}
        <div className="scroll-indicator">
          <div className="scroll-text">Learn more about community</div>
          <div className="scroll-arrow">↓</div>
        </div>
      </section>


      {/* Main Content Section with Sidebar Tabs */}
      <section className="main-content-section" style={{ display: 'flex', width: '100vw', height: '100vh', background: '#181c2f', position: 'relative', margin: 0, padding: 0 }}>
        <SidebarTabs />
      </section>

    </div>
  );
}

// SidebarTabs component
function SidebarTabs() {
  // Sidebar structure: each item can have subTabs
  const tabs = [
    { label: 'Intro' },
    { label: 'How to Start Or Join a Lobby' },
    {
      label: 'What is Vanilla Mod (Kekmod)',
      subTabs: [
        { label: 'Install in 30 sec' },
        { label: 'Uninstall in 5 sec (Just delete it)' }
      ]
    },
    { label: 'Server and Gameplay rules' }
  ];
  // activeTab: [mainTabIndex, subTabIndex or null]
  const [activeTab, setActiveTab] = useState([0, null]);

  return (
    <div style={{ display: 'flex', width: '100%', height: '100%' }}>
  <nav style={{ width: 'max-content', maxWidth: 'max-content', background: '#101325', color: '#fff', padding: '60px 0 40px 0', borderTopRightRadius: 20, borderBottomRightRadius: 20, boxShadow: '2px 0 10px #0002', display: 'flex', flexDirection: 'column', alignItems: 'flex-end', justifyContent: 'flex-start' }}>
        {tabs.map((tab, idx) => (
          <div key={tab.label} style={{ width: '100%' }}>
            <button
              onClick={() => setActiveTab([idx, null])}
              style={{
                background: activeTab[0] === idx && activeTab[1] === null ? '#00d4ff' : 'transparent',
                color: activeTab[0] === idx && activeTab[1] === null ? '#181c2f' : '#fff',
                border: 'none',
                borderRadius: '20px 0 0 20px',
                padding: '16px 32px',
                margin: '8px 0',
                fontWeight: 600,
                fontSize: '1.1rem',
                cursor: 'pointer',
                width: '100%',
                textAlign: 'right',
                transition: 'background 0.2s, color 0.2s'
              }}
            >
              {tab.label}
            </button>
            {/* Render sub-tabs if present (always visible) */}
            {tab.subTabs && (
              <div style={{ width: '100%', marginLeft: 0 }}>
                {tab.subTabs.map((sub, subIdx) => (
                  <button
                    key={sub.label}
                    onClick={() => setActiveTab([idx, subIdx])}
                    style={{
                      background: activeTab[0] === idx && activeTab[1] === subIdx ? '#00d4ff' : 'transparent',
                      color: activeTab[0] === idx && activeTab[1] === subIdx ? '#181c2f' : '#fff',
                      border: 'none',
                      borderRadius: '20px 0 0 20px',
                      padding: '12px 48px',
                      margin: '2px 0',
                      fontWeight: 500,
                      fontSize: '1rem',
                      cursor: 'pointer',
                      width: '100%',
                      textAlign: 'right',
                      transition: 'background 0.2s, color 0.2s',
                      opacity: 0.85
                    }}
                  >
                    {sub.label}
                  </button>
                ))}
              </div>
            )}
          </div>
        ))}
      </nav>
      <div style={{ flex: 1, padding: '48px 40px', color: '#fff', minHeight: 400, height: '100%', overflowY: 'auto', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: activeTab[0] === 2 && activeTab[1] === 0 ? 'flex-start' : 'flex-start' }}>
        {/* Intro section above tabs, only for Intro tab */}
        {activeTab[0] === 0 && (
          <div style={{ marginBottom: 32, background: '#23284a', borderRadius: 16, padding: '24px 32px', boxShadow: '0 2px 12px #0002', width: '100%', maxWidth: 800 }}>
            <h1 style={{ margin: 0, fontSize: '2.2rem', color: '#00d4ff' }}>Welcome to Democraciv</h1>
            <p style={{ margin: '12px 0 0 0', fontSize: '1.15rem', color: '#e0e0e0' }}>
              The home of competitive, fair-play Civilization V multiplayer. Use the tabs to learn how to join games, install the mod, and understand our rules and community.
            </p>
          </div>
        )}
        {activeTab[0] === 1 && (
          <div>
            <h2>How to Start Or Join a Lobby</h2>
            <p>Step 1: Join our Discord server and go to the <b>#LFG</b> channel to find other players.<br/>Step 2: Use the <b>#Draft</b> channel to create or join lobbies.<br/>Step 3: Follow lobby instructions and have fun!</p>
          </div>
        )}
        {activeTab[0] === 2 && activeTab[1] === null && (
          <div>
            <h2>What is Vanilla Mod (Kekmod)</h2>
            <p>The Vanilla Civ Mod (kekmod) is a lightweight mod for Civilization V: BNW that enables fair, competitive multiplayer with minimal changes. It is required for all games on this server. Use the sub-tabs to see install/uninstall instructions.</p>
          </div>
        )}
        {activeTab[0] === 2 && activeTab[1] === 0 && (
          <div style={{ width: '100%', maxWidth: 900, marginLeft: 200, display: 'flex', flexDirection: 'column', alignItems: 'flex-start', justifyContent: 'flex-start' }}>
            <div style={{ textAlign: 'left', marginBottom: 24, width: '100%' }}>
              <h2 style={{ marginBottom: 4, fontSize: '2.2rem', textAlign: 'left' }}>Vanilla Mod Installation Guide (30 sec)</h2>
              <div style={{ fontSize: '1.05rem', color: '#b0b0b0', marginBottom: 24, textAlign: 'left' }}>
                <span style={{ fontSize: '0.92rem', display: 'block', maxWidth: 500, marginLeft: 64 }}>
                  (To uninstall simply remove the files from folder)
                </span>
              </div>
            </div>
            <ol style={{ fontSize: '1.25rem', marginLeft: 0, paddingLeft: 0, width: '100%', maxWidth: 800, display: 'flex', flexDirection: 'column', alignItems: 'flex-start' }}>
              <li style={{ marginBottom: 36, width: '100%', textAlign: 'left' }}>
                <b>To Install download both Kekmod and Fishmap from #Patch</b>
                <div style={{ margin: '20px 0' }}>
                  <video controls style={{ maxWidth: 700, width: '100%', borderRadius: 16, boxShadow: '0 2px 16px #0003', display: 'block' }}>
                    <source src="/videos/downloadmapandmod.mp4" type="video/mp4" />
                    Your browser does not support the video tag.
                  </video>
                </div>
              </li>
              <li style={{ marginBottom: 36, width: '100%', textAlign: 'left' }}>
                <b>Move the uncompressed version of Kek Mod v1.4 to DLC folder</b><br/>
                <span style={{ fontSize: '1.08rem', color: '#b0b0b0' }}>Make sure you don't have other mods in folder other than EUI 1.28 or older</span>
              </li>
              <li style={{ marginBottom: 36, width: '100%', textAlign: 'left' }}>
                <b>Run UI_batch file</b><br/>
                <span style={{ fontSize: '1.08rem', color: '#b0b0b0' }}>(This is for anti cheat and to enable changes like pausing game and other functionalities)</span>
                <div style={{ margin: '20px 0' }}>
                  <video controls style={{ maxWidth: 700, width: '100%', borderRadius: 16, boxShadow: '0 2px 16px #0003', display: 'block' }}>
                    <source src="/videos/installguide.mp4" type="video/mp4" />
                    Your browser does not support the video tag.
                  </video>
                </div>
              </li>
              <li style={{ marginBottom: 36, width: '100%', textAlign: 'left' }}>
                <b>You are all set! Try it out by loading Singleplayer. Verify install by restarting game and load a single player game.<br/>You should now get additional options in game for UI</b>
                <div style={{ margin: '20px 0' }}>
                  <img src="/images/ingamescreenshot.png" alt="In-game screenshot" style={{ maxWidth: 700, width: '100%', borderRadius: 16, boxShadow: '0 2px 16px #0003', display: 'block' }} />
                </div>
              </li>
            </ol>
          </div>
        )}
        {activeTab[0] === 2 && activeTab[1] === 1 && (
          <div>
            <h2>Uninstall in 5 sec (Just delete it)</h2>
            <ol>
              <li>Open your Civilization V Mods folder.</li>
              <li>Delete the kekmod files from the folder.</li>
              <li>Restart Civilization V if it was running.</li>
            </ol>
          </div>
        )}
        {activeTab[0] === 3 && (
          <div>
            <h2>Server and Gameplay rules</h2>
            <ul>
              <li>No quitting without a vote</li>
              <li>All games use the kekmod</li>
              <li>Respect other players and follow Discord guidelines</li>
              <li>All rules and mods are voted on by the community</li>
              <li>See Discord for full rules list</li>
            </ul>
          </div>
        )}
      </div>
    </div>
  );
}


export default App;
